    "authorInfo": "\u0646\u0627\u0638\u0631\u06c1 \u0642\u0631\u0622\u0646 \u0622\u0633\u0627\u0646 \u062a\u062c\u0648\u06cc\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u0645\u0627\u0639\u062a \u062f\u0648\u0645\u060c \u0633\u0628\u0642 \u0646\u0645\u0628\u0631 4\u06d4",
    "urduText": "\u0640\u064f (\u0636\u064e\u0645\u064e\u0651\u0629)\\n\\n\u067e\u06cc\u0634 \u062d\u0631\u0641 \u06a9\u06d2 \u0627\u0648\u067e\u0631 \u0648\u0627\u0624 \u06a9\u06cc \u0637\u0631\u062d \u0686\u06be\u0648\u0679\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u06c1\u0648\u0646\u0679\u0648\u06ba \u06a9\u0648 \u06af\u0648\u0644 \u06a9\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u06be\u06cc\u0646\u0686\u06d2 '\u0627\u064f' \u06a9\u06cc \u0622\u0648\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
    "sections": [{
      "heading": "\u0633\u0628\u0642 \u06f4: \u067e\u06cc\u0634 (\u0627\u0639\u0627\u062f\u06c1)",
      "arabic": "\u0640\u064f (\u0636\u064e\u0645\u064e\u0651\u0629)",
      "text": "\u067e\u06cc\u0634 \u062d\u0631\u0641 \u06a9\u06d2 \u0627\u0648\u067e\u0631 \u0648\u0627\u0624 \u06a9\u06cc \u0637\u0631\u062d \u0686\u06be\u0648\u0679\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u06c1\u0648\u0646\u0679\u0648\u06ba \u06a9\u0648 \u06af\u0648\u0644 \u06a9\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u06be\u06cc\u0646\u0686\u06d2 '\u0627\u064f' \u06a9\u06cc \u0622\u0648\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
      "urduTranslation": "\u067e\u06cc\u0634 \u062d\u0631\u0641 \u06a9\u06d2 \u0627\u0648\u067e\u0631 \u0648\u0627\u0624 \u06a9\u06cc \u0637\u0631\u062d \u0686\u06be\u0648\u0679\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u06c1\u0648\u0646\u0679\u0648\u06ba \u06a9\u0648 \u06af\u0648\u0644 \u06a9\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u06be\u06cc\u0646\u0686\u06d2 '\u0627\u064f' \u06a9\u06cc \u0622\u0648\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
      "englishTranslation": "Dammah (Paish) represents a short 'u' vowel formed by rounding the lips without elongation.",
      "pashtoTranslation": "\u067e\u06d0\u069a \u062f \u0634\u0648\u0646\u0689\u0648 \u067e\u0647 \u06ab\u0631\u062f\u0648\u0644\u0648 \u0633\u0631\u0647 \u0628\u06d0 \u0644\u0647 \u06a9\u0634\u0648\u0644\u0648 \u0644\u0646\u0689 \u0644\u0648\u0633\u062a\u0644 \u06a9\u06cc\u0696\u064a.",
      "tashreeh": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u062a\u062c\u0648\u06cc\u062f \u06a9\u06cc \u062f\u0631\u0633\u062a \u0627\u062f\u0627\u0626\u06cc \u0627\u0648\u0631 \u0645\u0634\u0642 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2: \u0631\u064f\u0633\u064f\u0644\u064f - \u0635\u064f\u062d\u064f\u0641\u064f - \u0642\u064f\u062a\u0650\u0644\u064e - \u062e\u064f\u0644\u0650\u0642\u064e - \u0630\u064f\u0643\u0650\u0631\u064e - \u0633\u064f\u0626\u0650\u0644\u064e",
      "paras": [
            "\u0640\u064f (\u0636\u064e\u0645\u064e\u0651\u0629)",
            "\u067e\u06cc\u0634 \u062d\u0631\u0641 \u06a9\u06d2 \u0627\u0648\u067e\u0631 \u0648\u0627\u0624 \u06a9\u06cc \u0637\u0631\u062d \u0686\u06be\u0648\u0679\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u06c1\u0648\u0646\u0679\u0648\u06ba \u06a9\u0648 \u06af\u0648\u0644 \u06a9\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u06be\u06cc\u0646\u0686\u06d2 '\u0627\u064f' \u06a9\u06cc \u0622\u0648\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
            "\u0645\u0634\u0642\u06cc \u06a9\u0644\u0645\u0627\u062a: \u0631\u064f\u0633\u064f\u0644\u064f - \u0635\u064f\u062d\u064f\u0641\u064f - \u0642\u064f\u062a\u0650\u0644\u064e - \u062e\u064f\u0644\u0650\u0642\u064e - \u0630\u064f\u0643\u0650\u0631\u064e - \u0633\u064f\u0626\u0650\u0644\u064e"
      ]
}],
