    "title": "\u0633\u0628\u0642 \u06f6: \u062a\u0634\u062f\u06cc\u062f (\u0627\u0639\u0627\u062f\u06c1)",
    "titleEn": "Lesson 6: Tashdeed (Shaddah) Revision",
    "titlePs": "\u06f6 \u0644\u0648\u0633\u062a: \u062a\u0634\u062f\u06cc\u062f (\u0634\u064e\u062f\u0651\u0647) \u062a\u06a9\u0631\u0627\u0631",
    "author": "خیبر پختونخوا ٹیکسٹ بک بورڈ، پشاور — ناظرہ قرآن (جماعت دوم)",
    "authorInfo": "\u0646\u0627\u0638\u0631\u06c1 \u0642\u0631\u0622\u0646 \u0622\u0633\u0627\u0646 \u062a\u062c\u0648\u06cc\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u0645\u0627\u0639\u062a \u062f\u0648\u0645\u060c \u0633\u0628\u0642 \u0646\u0645\u0628\u0631 6\u06d4",
    "urduText": "\u0640\u0651 (\u0634\u064e\u062f\u064e\u0651\u0629)\\n\\n\u062c\u0633 \u062d\u0631\u0641 \u067e\u0631 \u062a\u0634\u062f\u06cc\u062f \u06c1\u0648 \u0627\u0633\u06d2 '\u0645\u0634\u062f\u062f' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0645\u0634\u062f\u062f \u062d\u0631\u0641 \u06a9\u0648 \u062f\u0648 \u0645\u0631\u062a\u0628\u06c1 \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2: \u067e\u06c1\u0644\u06cc \u0628\u0627\u0631 \u067e\u0686\u06be\u0644\u06d2 \u062d\u0631\u0641 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u0633\u0627\u06a9\u0646 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u0628\u0627\u0631 \u0627\u067e\u0646\u06cc \u062d\u0631\u06a9\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u06cc\u0633\u06d2: \u0631\u064e\u0628\u064e\u0651\u06d4",
    "sections": [{
      "heading": "\u0633\u0628\u0642 \u06f6: \u062a\u0634\u062f\u06cc\u062f (\u0627\u0639\u0627\u062f\u06c1)",
      "arabic": "\u0640\u0651 (\u0634\u064e\u062f\u064e\u0651\u0629)",
      "text": "\u062c\u0633 \u062d\u0631\u0641 \u067e\u0631 \u062a\u0634\u062f\u06cc\u062f \u06c1\u0648 \u0627\u0633\u06d2 '\u0645\u0634\u062f\u062f' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0645\u0634\u062f\u062f \u062d\u0631\u0641 \u06a9\u0648 \u062f\u0648 \u0645\u0631\u062a\u0628\u06c1 \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2: \u067e\u06c1\u0644\u06cc \u0628\u0627\u0631 \u067e\u0686\u06be\u0644\u06d2 \u062d\u0631\u0641 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u0633\u0627\u06a9\u0646 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u0628\u0627\u0631 \u0627\u067e\u0646\u06cc \u062d\u0631\u06a9\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u06cc\u0633\u06d2: \u0631\u064e\u0628\u064e\u0651\u06d4",
      "urduTranslation": "\u062c\u0633 \u062d\u0631\u0641 \u067e\u0631 \u062a\u0634\u062f\u06cc\u062f \u06c1\u0648 \u0627\u0633\u06d2 '\u0645\u0634\u062f\u062f' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0645\u0634\u062f\u062f \u062d\u0631\u0641 \u06a9\u0648 \u062f\u0648 \u0645\u0631\u062a\u0628\u06c1 \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2: \u067e\u06c1\u0644\u06cc \u0628\u0627\u0631 \u067e\u0686\u06be\u0644\u06d2 \u062d\u0631\u0641 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u0633\u0627\u06a9\u0646 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u0628\u0627\u0631 \u0627\u067e\u0646\u06cc \u062d\u0631\u06a9\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u06cc\u0633\u06d2: \u0631\u064e\u0628\u064e\u0651\u06d4",
      "englishTranslation": "Tashdeed (Shaddah) doubles the consonant: first silent, second vocalized.",
      "pashtoTranslation": "\u062a\u0634\u062f\u06cc\u062f \u0648\u0627\u0644\u0627 \u062a\u0648\u0631\u06cc \u062f\u0648\u0647 \u0681\u0644\u0647 \u0648\u06cc\u0644 \u06a9\u06cc\u0696\u064a: \u0644\u0648\u0645\u0693\u06cc \u0633\u0627\u06a9\u0646 \u0627\u0648 \u062f\u0648\u06cc\u0645 \u0644\u0647 \u062d\u0631\u06a9\u062a \u0633\u0631\u0647.",
      "tashreeh": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u062a\u062c\u0648\u06cc\u062f \u06a9\u06cc \u062f\u0631\u0633\u062a \u0627\u062f\u0627\u0626\u06cc \u0627\u0648\u0631 \u0645\u0634\u0642 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2: \u0631\u064e\u0628\u064e\u0651 - \u0625\u0650\u0646\u064e\u0651 - \u062b\u064f\u0645\u064e\u0651 - \u0642\u064f\u0644\u0652 - \u062d\u064e\u0642\u064e\u0651 - \u0634\u064e\u062f\u064e\u0651 - \u0645\u064e\u062f\u064e\u0651",
      "paras": [
            "\u0640\u0651 (\u0634\u064e\u062f\u064e\u0651\u0629)",
            "\u062c\u0633 \u062d\u0631\u0641 \u067e\u0631 \u062a\u0634\u062f\u06cc\u062f \u06c1\u0648 \u0627\u0633\u06d2 '\u0645\u0634\u062f\u062f' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0645\u0634\u062f\u062f \u062d\u0631\u0641 \u06a9\u0648 \u062f\u0648 \u0645\u0631\u062a\u0628\u06c1 \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2: \u067e\u06c1\u0644\u06cc \u0628\u0627\u0631 \u067e\u0686\u06be\u0644\u06d2 \u062d\u0631\u0641 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u0633\u0627\u06a9\u0646 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u0628\u0627\u0631 \u0627\u067e\u0646\u06cc \u062d\u0631\u06a9\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u062c\u06cc\u0633\u06d2: \u0631\u064e\u0628\u064e\u0651\u06d4",
            "\u0645\u0634\u0642\u06cc \u06a9\u0644\u0645\u0627\u062a: \u0631\u064e\u0628\u064e\u0651 - \u0625\u0650\u0646\u064e\u0651 - \u062b\u064f\u0645\u064e\u0651 - \u0642\u064f\u0644\u0652 - \u062d\u064e\u0642\u064e\u0651 - \u0634\u064e\u062f\u064e\u0651 - \u0645\u064e\u062f\u064e\u0651"
      ]
}],
