      "tashreeh": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u062a\u062c\u0648\u06cc\u062f \u06a9\u06cc \u062f\u0631\u0633\u062a \u0627\u062f\u0627\u0626\u06cc \u0627\u0648\u0631 \u0645\u0634\u0642 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2: \u0628\u064e\u0627 \u0628\u064f\u0648 \u0628\u0650\u064a - \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0642\u0650\u064a\u0644\u064e - \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u064e\u0627",
