                "urdu": "\u062a\u062c\u0648\u06cc\u062f\u06cc \u0642\u0648\u0627\u0639\u062f \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u06cc\u06ba: \u0633\u0628\u0642 \u06f9: \u062d\u0631\u0648\u0641\u0650 \u0645\u0642\u0637\u0639\u0627\u062a",
