      "longQuestions": [
        {
                "id": "cls2-naz-ch12-lq1",
                "question": "\u0633\u0628\u0642 \"\u0633\u0628\u0642 \u06f1\u06f2: \u063a\u0646\u06c1 \u0648 \u0627\u062e\u0641\u0627\u0621 (\u0627\u0639\u0627\u062f\u06c1)\" \u06a9\u06d2 \u0628\u0646\u06cc\u0627\u062f\u06cc \u062a\u062c\u0648\u06cc\u062f\u06cc \u0642\u0648\u0627\u0639\u062f \u0627\u0648\u0631 \u0645\u0634\u0642\u06cc \u06a9\u0644\u0645\u0627\u062a \u06a9\u0648 \u062a\u0641\u0635\u06cc\u0644 \u0633\u06d2 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0646\u0627\u06a9 \u06a9\u06d2 \u0628\u0627\u0646\u0633\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0627\u0644\u0641 \u06a9\u06d2 \u0628\u0631\u0627\u0628\u0631 \u06af\u0646\u06af\u0646\u06cc \u0622\u0648\u0627\u0632 \u0646\u06a9\u0627\u0644\u0646\u06d2 \u06a9\u0648 '\u063a\u0646\u06c1' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0646\u0648\u0646 \u0645\u0634\u062f\u062f\u060c \u0645\u06cc\u0645 \u0645\u0634\u062f\u062f \u0627\u0648\u0631 \u0646\u0648\u0646 \u0633\u0627\u06a9\u0646 \u0648 \u062a\u0646\u0648\u06cc\u0646 \u06a9\u06d2 \u0627\u062e\u0641\u0627\u0621 \u0648 \u0627\u062f\u063a\u0627\u0645 \u0645\u06cc\u06ba \u063a\u0646\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u0645\u0634\u0642\u06cc \u06a9\u0644\u0645\u0627\u062a: \u0625\u0650\u0646\u064e\u0651 - \u0639\u064e\u0645\u064e\u0651 - \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e - \u0643\u064f\u0646\u062a\u064f\u0645\u0652 - \u0623\u064e\u0646\u062a\u064f\u0645\u0652 - \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652",
                "urdu": "\u062a\u062c\u0648\u06cc\u062f\u06cc \u0642\u0648\u0627\u0639\u062f \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u06cc\u06ba: \u0633\u0628\u0642 \u06f1\u06f2: \u063a\u0646\u06c1 \u0648 \u0627\u062e\u0641\u0627\u0621 (\u0627\u0639\u0627\u062f\u06c1)",
                "urduAns": "\u0646\u0627\u06a9 \u06a9\u06d2 \u0628\u0627\u0646\u0633\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0627\u0644\u0641 \u06a9\u06d2 \u0628\u0631\u0627\u0628\u0631 \u06af\u0646\u06af\u0646\u06cc \u0622\u0648\u0627\u0632 \u0646\u06a9\u0627\u0644\u0646\u06d2 \u06a9\u0648 '\u063a\u0646\u06c1' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0646\u0648\u0646 \u0645\u0634\u062f\u062f\u060c \u0645\u06cc\u0645 \u0645\u0634\u062f\u062f \u0627\u0648\u0631 \u0646\u0648\u0646 \u0633\u0627\u06a9\u0646 \u0648 \u062a\u0646\u0648\u06cc\u0646 \u06a9\u06d2 \u0627\u062e\u0641\u0627\u0621 \u0648 \u0627\u062f\u063a\u0627\u0645 \u0645\u06cc\u06ba \u063a\u0646\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u0644\u0647 \u067e\u0648\u0632\u06d0 \u0685\u062e\u0647 \u0646\u0631\u06cc \u063a\u0696 \u0631\u0627\u0627\u06cc\u0633\u062a\u0644\u0648 \u062a\u0647 \u063a\u0646\u0647 \u0648\u0627\u064a\u064a.",
                "pashtoAns": "\u0625\u0650\u0646\u064e\u0651 - \u0639\u064e\u0645\u064e\u0651 - \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e - \u0643\u064f\u0646\u062a\u064f\u0645\u0652 - \u0623\u064e\u0646\u062a\u064f\u0645\u0652 - \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652"
        }
]
