                "ans": "\u0646\u0627\u06a9 \u06a9\u06d2 \u0628\u0627\u0646\u0633\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0627\u0644\u0641 \u06a9\u06d2 \u0628\u0631\u0627\u0628\u0631 \u06af\u0646\u06af\u0646\u06cc \u0622\u0648\u0627\u0632 \u0646\u06a9\u0627\u0644\u0646\u06d2 \u06a9\u0648 '\u063a\u0646\u06c1' \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0646\u0648\u0646 \u0645\u0634\u062f\u062f\u060c \u0645\u06cc\u0645 \u0645\u0634\u062f\u062f \u0627\u0648\u0631 \u0646\u0648\u0646 \u0633\u0627\u06a9\u0646 \u0648 \u062a\u0646\u0648\u06cc\u0646 \u06a9\u06d2 \u0627\u062e\u0641\u0627\u0621 \u0648 \u0627\u062f\u063a\u0627\u0645 \u0645\u06cc\u06ba \u063a\u0646\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"
