                "urdu": "\u067e\u06c1\u0644\u06d2 \u067e\u0627\u0631\u06d2 \u06a9\u0627 \u0622\u063a\u0627\u0632 \u06a9\u0646 \u062d\u0631\u0648\u0641 \u0633\u06d2 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u0644\u0648\u0645\u0693\u06cd \u0633\u067e\u0627\u0631\u06d0 \u067e\u06cc\u0644 \u067e\u0647 \u0685\u0647 \u0634\u064a \u062f\u06cc\u061f"
