                "explanation": "\u067e\u06c1\u0644\u06d2 \u067e\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u0645\u06a9\u0645\u0644 \u0633\u0648\u0631\u06c3 \u0627\u0644\u0641\u0627\u062a\u062d\u06c1 \u0627\u0648\u0631 \u0633\u0648\u0631\u06c3 \u0627\u0644\u0628\u0642\u0631\u06c3 \u06a9\u06d2 \u06f1\u06f6 \u0631\u06a9\u0648\u0639 \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u06d4",
                "urdu": "\u067e\u06c1\u0644\u06d2 \u067e\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u0648\u0646 \u0633\u06cc \u0633\u0648\u0631\u062a\u06cc\u06ba \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u061f",
                "pashto": "\u06a9\u0648\u0645 \u0633\u0648\u0631\u062a\u0648\u0646\u0647 \u067e\u0647 \u06a9\u06d0 \u0631\u0627\u063a\u0644\u064a\u061f"
