                "urdu": "\u067e\u06c1\u0644\u06d2 \u067e\u0627\u0631\u06d2 \u06a9\u0627 \u0622\u063a\u0627\u0632 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f"
