                "question": "\u062f\u0648\u0633\u0631\u06d2 \u067e\u0627\u0631\u06d2 \u06a9\u0627 \u067e\u06c1\u0644\u0627 \u0644\u0641\u0638 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "answer": "\u062f\u0648\u0633\u0631\u06d2 \u067e\u0627\u0631\u06d2 \u06a9\u0627 \u067e\u06c1\u0644\u0627 \u0644\u0641\u0638 '\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f' \u06c1\u06d2\u06d4",
                "urdu": "\u067e\u06c1\u0644\u0627 \u0644\u0641\u0638 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u062f\u0648\u06cc\u0645\u06d0 \u0633\u067e\u0627\u0631\u06d0 \u0644\u0648\u0645\u0693\u06cc \u062a\u0648\u0631\u06cc \u0685\u0647 \u062f\u06cc\u061f",
