                "question": "\u062f\u0648\u0633\u0631\u06d2 \u067e\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u0642\u0628\u0644\u06c1 \u06a9\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u06a9\u06cc\u0627 \u062d\u06a9\u0645 \u06c1\u06d2\u061f",
                "answer": "\u0645\u0633\u0644\u0645\u0627\u0646\u0648\u06ba \u06a9\u0627 \u0642\u0628\u0644\u06c1 \u0628\u06cc\u062a \u0627\u0644\u0645\u0642\u062f\u0633 \u0633\u06d2 \u06a9\u0639\u0628\u06c3 \u0627\u0644\u0644\u06c1 \u0634\u0631\u06cc\u0641 \u06a9\u06cc \u0637\u0631\u0641 \u062a\u0628\u062f\u06cc\u0644 \u06a9\u06cc\u0627 \u06af\u06cc\u0627\u06d4",
                "urdu": "\u062a\u062d\u0648\u06cc\u0644 \u0642\u0628\u0644\u06c1 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u0642\u0628\u0644\u06d0 \u0628\u062f\u0644\u06d0\u062f\u0644 \u0685\u0647 \u062d\u06a9\u0645 \u0648\u061f",
                "pashtoAns": "\u06a9\u0639\u0628\u0647 \u0634\u0631\u06cc\u0641\u0647 \u062f \u0645\u0633\u0644\u0645\u0627\u0646\u0627\u0646\u0648 \u0646\u0648\u06d0 \u0627\u0648 \u0627\u0628\u062f\u064a \u0642\u0628\u0644\u0647 \u0648\u067c\u0627\u06a9\u0644 \u0634\u0648\u0647."
